//! Differential properties for the walkers that read JSON without parsing it (`peek`'s scanners
//! and span reads), on the same generated bytes delivered whole, byte by byte, and cut at random:
//!
//! - against `props_support::old_peek`, the walkers as they stood before they shared one lexer:
//!   the behavioural oracle. They must agree on every input, malformed and truncated included,
//!   because a malformed body's reading is still an answer a caller acts on.
//! - against `serde_json`, the semantic oracle (how a provider reads the body), on valid JSON.
//!
//! Bodies are written by hand, from a tree that keeps what a `Value` normalizes away: duplicate
//! keys, member order, a number's spelling, `\u` escapes (surrogate pairs included) in keys and
//! values, whitespace anywhere JSON allows it. Then some are broken: truncated, or a byte
//! inserted, deleted or replaced, with bytes that matter to a lexer (quotes, backslashes,
//! brackets) drawn most often.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

mod props_support;

use beyond_ai::peek::{self, Kept, ModelScanner};
use props_support::old_peek as old;
use props_support::*;
use proptest::prelude::*;
use serde_json::Value;

// --- generated JSON -------------------------------------------------------------------------

/// A JSON tree as written: duplicate keys and number spellings survive.
#[derive(Clone, Debug)]
enum J {
    Null,
    Bool(bool),
    Num(String),
    Str(String),
    Arr(Vec<J>),
    Obj(Vec<(String, J)>),
}

/// The keys the walkers look for, their near misses, and a few ordinary ones.
const KEYS: &[&str] = &[
    "model",
    "stream",
    "stream_options",
    "max_tokens",
    "max_completion_tokens",
    "max_output_tokens",
    "message",
    "response",
    "id",
    "provider",
    "service_tier",
    "speed",
    "inference_geo",
    "plugins",
    "container",
    "type",
    "messages",
    "content",
    "include_usage",
    "Model",
    "models",
    "model ",
    "",
];

/// Every form a JSON number takes: integers, signs, fractions, exponents of either case and sign,
/// and integers past `u64`.
fn number() -> impl Strategy<Value = String> {
    prop_oneof![
        4 => "-?(0|[1-9][0-9]{0,6})",
        2 => "-?(0|[1-9][0-9]{0,4})\\.[0-9]{1,4}",
        // Two exponent digits at most: serde reads a number past `f64` as an error, not infinity.
        2 => "-?(0|[1-9][0-9]{0,3})(\\.[0-9]{1,3})?[eE][+-]?[0-9]{1,2}",
        1 => Just("18446744073709551616".to_owned()),
        1 => Just("-0".to_owned()),
        1 => Just("0e0".to_owned()),
    ]
}

/// String content: model ids, adversarial text (every escape, astral and control characters),
/// and strings long enough to pass every capture cap and many chunk boundaries.
fn string() -> impl Strategy<Value = String> {
    prop_oneof![
        4 => "[a-z0-9][a-z0-9./:-]{0,24}",
        4 => text(6),
        1 => prop::sample::select(KEYS).prop_map(str::to_owned),
        1 => "[a-z]{250,600}",
        1 => (0usize..80_000).prop_map(|n| "x".repeat(n)),
        1 => (1usize..400).prop_map(|n| "\"\\é😀/\n".repeat(n)),
    ]
}

fn key() -> impl Strategy<Value = String> {
    prop_oneof![
        8 => prop::sample::select(KEYS).prop_map(str::to_owned),
        2 => text(3),
        1 => "[a-z]{250,300}",
    ]
}

fn leaf() -> impl Strategy<Value = J> {
    prop_oneof![
        1 => Just(J::Null),
        1 => any::<bool>().prop_map(J::Bool),
        3 => number().prop_map(J::Num),
        5 => string().prop_map(J::Str),
    ]
}

fn tree() -> impl Strategy<Value = J> {
    leaf().prop_recursive(5, 64, 6, |inner| {
        prop_oneof![
            prop::collection::vec(inner.clone(), 0..5).prop_map(J::Arr),
            prop::collection::vec((key(), inner), 0..6).prop_map(J::Obj),
        ]
    })
}

/// A root object, sometimes wrapped deep: a member whose value is `depth` levels of arrays and
/// objects (past any depth a walker special-cases).
fn root() -> impl Strategy<Value = J> {
    (
        prop::collection::vec((key(), tree()), 0..8),
        prop::option::weighted(0.15, (2usize..80, any::<bool>(), tree())),
    )
        .prop_map(|(mut members, deep)| {
            if let Some((depth, objects, mut v)) = deep {
                for d in 0..depth {
                    v = if objects ^ (d % 2 == 0) {
                        J::Obj(vec![("model".to_owned(), v)])
                    } else {
                        J::Arr(vec![v])
                    };
                }
                members.insert(members.len() / 2, ("deep".to_owned(), v));
            }
            J::Obj(members)
        })
}

/// The writer's choices, drawn in turn: whitespace, and how each character of a string is spelled.
struct Dice<'a> {
    d: &'a [u8],
    k: usize,
}

impl Dice<'_> {
    fn next(&mut self) -> u8 {
        self.k += 1;
        self.d
            .get(self.k % self.d.len().max(1))
            .copied()
            .unwrap_or(0)
    }

    fn ws(&mut self) -> &'static str {
        match self.next() % 8 {
            0..=3 => "",
            4 => " ",
            5 => "\n",
            6 => "\t ",
            _ => "\r\n  ",
        }
    }
}

/// `s` quoted, each character spelled as sent or (by the dice) escaped: `\uXXXX` in either hex
/// case, a surrogate pair past the BMP, `\/`. A character JSON requires escaped always is.
fn quote(s: &str, dice: &mut Dice, out: &mut String) {
    use std::fmt::Write as _;
    // Most strings are spelled plainly, as most clients send them; the rest escape often.
    let rate = match dice.next() % 4 {
        0 => 3,
        _ => 0,
    };
    out.push('"');
    for c in s.chars() {
        let roll = if rate == 0 { 255 } else { dice.next() % 8 };
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '/' if roll < rate => out.push_str("\\/"),
            c if (c as u32) < 0x20 || roll < rate => {
                let upper = dice.next().is_multiple_of(2);
                let mut buf = [0u16; 2];
                for u in c.encode_utf16(&mut buf) {
                    if upper {
                        write!(out, "\\u{u:04X}").unwrap();
                    } else {
                        write!(out, "\\u{u:04x}").unwrap();
                    }
                }
            }
            c => out.push(c),
        }
    }
    out.push('"');
}

fn write(v: &J, dice: &mut Dice, out: &mut String) {
    match v {
        J::Null => out.push_str("null"),
        J::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        J::Num(n) => out.push_str(n),
        J::Str(s) => quote(s, dice, out),
        J::Arr(a) => {
            out.push('[');
            for (i, x) in a.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                out.push_str(dice.ws());
                write(x, dice, out);
                out.push_str(dice.ws());
            }
            out.push(']');
        }
        J::Obj(m) => {
            out.push('{');
            for (i, (k, x)) in m.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                out.push_str(dice.ws());
                quote(k, dice, out);
                out.push_str(dice.ws());
                out.push(':');
                out.push_str(dice.ws());
                write(x, dice, out);
                out.push_str(dice.ws());
            }
            out.push('}');
        }
    }
}

/// One way to break a body.
#[derive(Clone, Debug)]
enum Break {
    Truncate(usize),
    Insert(usize, u8),
    Delete(usize),
    Replace(usize, u8),
}

/// The bytes that steer a lexer, drawn most often, then any byte.
fn steering_byte() -> impl Strategy<Value = u8> {
    prop_oneof![
        4 => prop::sample::select(b"\"\\{}[]:, u0tn-".to_vec()),
        1 => any::<u8>(),
    ]
}

fn breaks() -> impl Strategy<Value = Vec<Break>> {
    let one = prop_oneof![
        1 => any::<usize>().prop_map(Break::Truncate),
        2 => (any::<usize>(), steering_byte()).prop_map(|(a, b)| Break::Insert(a, b)),
        2 => any::<usize>().prop_map(Break::Delete),
        2 => (any::<usize>(), steering_byte()).prop_map(|(a, b)| Break::Replace(a, b)),
    ];
    prop::collection::vec(one, 1..4)
}

/// Where a break lands: three times in four on a byte that steers a lexer (a quote, backslash,
/// bracket, `:` or `,`), since a break inside a long string's text changes nothing a walker
/// reads; otherwise anywhere, the end included.
fn place(bytes: &[u8], at: usize) -> usize {
    let steering: Vec<usize> = bytes
        .iter()
        .enumerate()
        .filter(|(_, c)| matches!(c, b'"' | b'\\' | b'{' | b'}' | b'[' | b']' | b':' | b','))
        .map(|(i, _)| i)
        .collect();
    if !at.is_multiple_of(4) && !steering.is_empty() {
        steering[(at / 4) % steering.len()]
    } else {
        at % (bytes.len() + 1)
    }
}

fn apply(bytes: &mut Vec<u8>, b: &Break) {
    let len = bytes.len();
    match *b {
        Break::Truncate(at) => bytes.truncate(place(bytes, at)),
        Break::Insert(at, c) => bytes.insert(place(bytes, at), c),
        Break::Delete(at) => {
            let at = place(bytes, at);
            if at < len {
                bytes.remove(at);
            }
        }
        Break::Replace(at, c) => {
            let at = place(bytes, at);
            if at < len {
                bytes[at] = c;
            }
        }
    }
}

/// A generated input: valid JSON (`valid`), or bytes broken from it, or raw bytes.
#[derive(Clone, Debug)]
struct Input {
    bytes: Vec<u8>,
    valid: bool,
    /// The tree the bytes were written from, when they are still exactly it.
    tree: Option<J>,
}

fn written(v: &J, dice: &[u8], sse: bool) -> Vec<u8> {
    let mut d = Dice { d: dice, k: 0 };
    let mut out = String::new();
    if sse {
        // A response stream: events framed as SSE, the JSON after `data: `.
        out.push_str("event: message_start\ndata: ");
    }
    out.push_str(d.ws());
    write(v, &mut d, &mut out);
    out.push_str(d.ws());
    if sse {
        out.push_str("\n\ndata: {\"type\":\"ping\"}\n\n");
    }
    out.into_bytes()
}

fn input() -> impl Strategy<Value = Input> {
    let valid = (root(), prop::collection::vec(any::<u8>(), 1..32)).prop_map(|(v, dice)| Input {
        bytes: written(&v, &dice, false),
        valid: true,
        tree: Some(v),
    });
    let nested_response = (
        prop::sample::select(vec!["message", "response"]),
        root(),
        root(),
        prop::collection::vec(any::<u8>(), 1..32),
        any::<bool>(),
    )
        .prop_map(|(nest, inner, outer, dice, sse)| {
            let J::Obj(mut members) = outer else {
                unreachable!()
            };
            members.insert(0, (nest.to_owned(), inner));
            let v = J::Obj(members);
            Input {
                bytes: written(&v, &dice, sse),
                valid: !sse,
                tree: (!sse).then_some(v),
            }
        });
    let any_root =
        (tree(), prop::collection::vec(any::<u8>(), 1..32)).prop_map(|(v, dice)| Input {
            bytes: written(&v, &dice, false),
            valid: true,
            tree: Some(v),
        });
    let broken = (
        prop_oneof![root(), tree()],
        prop::collection::vec(any::<u8>(), 1..32),
        breaks(),
    )
        .prop_map(|(v, dice, breaks)| {
            let mut bytes = written(&v, &dice, false);
            for b in &breaks {
                apply(&mut bytes, b);
            }
            let valid = serde_json::from_slice::<Value>(&bytes).is_ok();
            Input {
                bytes,
                valid,
                tree: None,
            }
        });
    let raw = prop::collection::vec(steering_byte(), 0..200).prop_map(|bytes| Input {
        valid: serde_json::from_slice::<Value>(&bytes).is_ok(),
        bytes,
        tree: None,
    });
    let soup = prop::collection::vec(token(), 0..40).prop_map(|t| {
        let bytes = format!("{{{}", t.concat()).into_bytes();
        Input {
            valid: serde_json::from_slice::<Value>(&bytes).is_ok(),
            bytes,
            tree: None,
        }
    });
    prop_oneof![
        4 => valid,
        2 => nested_response,
        1 => any_root,
        4 => broken,
        4 => soup,
        1 => raw,
    ]
}

/// One JSON token, or a near miss: the keys the walkers look for (plainly and escaped), values
/// of every kind, structure. A run of them after a `{` is mostly malformed JSON in the ways that
/// split one walker's grammar from another's: a missing `,` or `:`, a value where a key goes, a
/// container closed by the wrong bracket.
fn token() -> impl Strategy<Value = &'static str> {
    prop::sample::select(vec![
        "\"model\"",
        "\"mod\\u0065l\"",
        "\"stream\"",
        "\"str\\u0065am\"",
        "\"stream_options\"",
        "\"stream\\u005foptions\"",
        "\"max_tokens\"",
        "\"max\\u005ftokens\"",
        "\"max_completion_tokens\"",
        "\"max_output_tokens\"",
        "\"message\"",
        "\"response\"",
        "\"id\"",
        "\"provider\"",
        "\"service_tier\"",
        "\"speed\"",
        "\"plugins\"",
        "\"container\"",
        "\"type\"",
        "\"image\"",
        "\"x\\\"y\"",
        "\"a\\\\\"",
        "\"\\ud83d\\ude00\"",
        "\"gpt-5\"",
        "true",
        "false",
        "null",
        "nul",
        "12",
        "-1",
        "1.5",
        "1e5",
        "0",
        "{",
        "}",
        "[",
        "]",
        ":",
        ":",
        ",",
        ",",
        " ",
        "\n",
        "\\",
    ])
}

/// The chunkings every input is delivered in: whole, byte by byte, and cut at random.
fn chunkings(bytes: &[u8], cuts: &[usize]) -> Vec<Vec<Vec<u8>>> {
    vec![
        vec![bytes.to_vec()],
        bytes.iter().map(|&b| vec![b]).collect(),
        chunk(bytes, cuts),
    ]
}

fn shown(bytes: &[u8]) -> String {
    let s = String::from_utf8_lossy(bytes);
    if s.len() > 600 {
        let cut = (0..=600)
            .rev()
            .find(|&i| s.is_char_boundary(i))
            .unwrap_or(0);
        format!("{}… ({} bytes)", &s[..cut], bytes.len())
    } else {
        s.into_owned()
    }
}

// --- the streaming scanner --------------------------------------------------------------------

/// Which scan: request (`new`) or response (`for_response`), and what it keeps beside `model`.
#[derive(Clone, Copy, Debug)]
enum Scan {
    Request,
    RequestKnobs,
    Response,
    ResponseKept,
}

const SCANS: [Scan; 4] = [
    Scan::Request,
    Scan::RequestKnobs,
    Scan::Response,
    Scan::ResponseKept,
];

/// What one scan reports: the model, whether it closed, and each kept value.
type Scanned = (Option<String>, bool, Vec<Option<String>>);

fn scan_new(scan: Scan, chunks: &[Vec<u8>]) -> Scanned {
    let (mut s, kept) = match scan {
        Scan::Request => (ModelScanner::new(), None),
        Scan::RequestKnobs => (ModelScanner::new(), Some(Kept::request_knobs())),
        Scan::Response => (ModelScanner::for_response(), None),
        Scan::ResponseKept => (ModelScanner::for_response(), Some(Kept::response())),
    };
    let mut kept = kept;
    for c in chunks {
        match kept.as_mut() {
            Some(k) => s.feed_keeping(c, k),
            None => s.feed(c),
        }
    }
    let values = (0..6)
        .map(|i| kept.as_ref().and_then(|k| k.get(i)).map(str::to_owned))
        .collect();
    (s.take_model(), s.found(), values)
}

fn scan_old(scan: Scan, chunks: &[Vec<u8>]) -> Scanned {
    let (mut s, kept) = match scan {
        Scan::Request => (old::ModelScanner::new(), None),
        Scan::RequestKnobs => (old::ModelScanner::new(), Some(old::Kept::request_knobs())),
        Scan::Response => (old::ModelScanner::for_response(), None),
        Scan::ResponseKept => (
            old::ModelScanner::for_response(),
            Some(old::Kept::response()),
        ),
    };
    let mut kept = kept;
    for c in chunks {
        match kept.as_mut() {
            Some(k) => s.feed_keeping(c, k),
            None => s.feed(c),
        }
    }
    let values = (0..6)
        .map(|i| kept.as_ref().and_then(|k| k.get(i)).map(str::to_owned))
        .collect();
    (s.take_model(), s.found(), values)
}

/// `ModelScanner`, every flavour, every chunking, reports what the old scanner reports.
#[test]
fn prop_model_scanner_agrees_with_the_old_walker() {
    check(
        "prop_model_scanner_agrees_with_the_old_walker",
        (input(), prop::collection::vec(any::<usize>(), 0..12)),
        |(input, cuts)| {
            let whole = vec![input.bytes.clone()];
            for scan in SCANS {
                let want = scan_old(scan, &whole);
                for chunks in chunkings(&input.bytes, &cuts) {
                    let got = scan_new(scan, &chunks);
                    prop_assert_eq!(
                        &got,
                        &want,
                        "{:?} in {} chunks: {}",
                        scan,
                        chunks.len(),
                        shown(&input.bytes)
                    );
                }
            }
            Ok(())
        },
    );
}

/// On valid JSON the streaming scanner reads the root `model` serde reads, when there is one,
/// once, as a string short enough to keep.
#[test]
fn prop_model_scanner_reads_the_model_serde_reads() {
    check(
        "prop_model_scanner_reads_the_model_serde_reads",
        (input(), prop::collection::vec(any::<usize>(), 0..12)),
        |(input, cuts)| {
            let Some(J::Obj(members)) = &input.tree else {
                return Ok(());
            };
            let Ok(Value::Object(root)) = serde_json::from_slice::<Value>(&input.bytes) else {
                panic!("generator wrote invalid JSON: {}", shown(&input.bytes));
            };
            if members.iter().filter(|(k, _)| k == "model").count() != 1 {
                return Ok(());
            }
            for chunks in chunkings(&input.bytes, &cuts) {
                let (model, _, _) = scan_new(Scan::Request, &chunks);
                match root["model"].as_str() {
                    Some(id) if id.len() < peek::MAX_CAPTURE => {
                        prop_assert_eq!(model.as_deref(), Some(id), "{}", shown(&input.bytes))
                    }
                    Some(_) => {}
                    None => prop_assert_eq!(model, None, "{}", shown(&input.bytes)),
                }
            }
            Ok(())
        },
    );
}

// --- the buffered scan ------------------------------------------------------------------------

/// Every field of a buffered scan, as one comparable value.
type Fields = (
    Option<String>,
    Option<usize>,
    Option<usize>,
    Option<(usize, usize)>,
    bool,
    [Option<(usize, usize)>; 3],
    bool,
    [Option<usize>; 3],
    bool,
);

fn fields_new(b: &[u8]) -> Fields {
    let s = peek::scan_buffered(b);
    (
        s.model,
        s.inject_at,
        s.stream_options_at,
        s.model_span,
        s.duplicate_model,
        s.limit_spans,
        s.inexact_limit,
        s.limit_keys,
        s.stream_options_ambiguous,
    )
}

fn fields_old(b: &[u8]) -> Fields {
    let s = old::scan_buffered(b);
    (
        s.model,
        s.inject_at,
        s.stream_options_at,
        s.model_span,
        s.duplicate_model,
        s.limit_spans,
        s.inexact_limit,
        s.limit_keys,
        s.stream_options_ambiguous,
    )
}

/// `scan_buffered` answers exactly as the old fused walk on any bytes.
#[test]
fn prop_buffered_scan_agrees_with_the_old_walker() {
    check(
        "prop_buffered_scan_agrees_with_the_old_walker",
        input(),
        |input| {
            prop_assert_eq!(
                fields_new(&input.bytes),
                fields_old(&input.bytes),
                "{}",
                shown(&input.bytes)
            );
            Ok(())
        },
    );
}

// --- the span reads ---------------------------------------------------------------------------

/// Offsets worth starting a span read at: every bracket and quote, and the first byte that is
/// not whitespace (a value's start).
fn starts(b: &[u8]) -> Vec<usize> {
    let mut at: Vec<usize> = b
        .iter()
        .enumerate()
        .filter(|(_, c)| matches!(c, b'{' | b'[' | b'"'))
        .map(|(i, _)| i)
        .take(64)
        .collect();
    if let Some(first) = b.iter().position(|c| !c.is_ascii_whitespace()) {
        at.push(first);
    }
    at
}

/// A span edit: changes the body in place, `true` when it did.
type Edit = fn(&mut Vec<u8>) -> bool;

const TYPES: &[&str] = &["image", "image_url", "file", "input_file"];

/// Every span read, from every start: value and string ends, members and elements (and where
/// each iterator says the container closed), the last member of a key, string decoding, typed
/// members, the structure count, and each span edit's result.
#[test]
fn prop_span_reads_agree_with_the_old_walkers() {
    check(
        "prop_span_reads_agree_with_the_old_walkers",
        input(),
        |input| {
            let b = &input.bytes[..];
            let s = shown(b);
            for at in starts(b) {
                prop_assert_eq!(
                    peek::value_end(b, at),
                    old::value_end(b, at),
                    "at {}: {}",
                    at,
                    s
                );
                let new: Vec<_> = peek::members(b, at)
                    .map(|m| m.map(|m| (m.key, m.value)))
                    .collect();
                let was: Vec<_> = old::members(b, at)
                    .map(|m| m.map(|m| (m.key, m.value)))
                    .collect();
                prop_assert_eq!(&new, &was, "members at {}: {}", at, s);
                let (mut n, mut o) = (peek::members(b, at), old::members(b, at));
                n.by_ref().for_each(drop);
                o.by_ref().for_each(drop);
                prop_assert_eq!(n.end(), o.end(), "members end at {}: {}", at, s);
                let new: Vec<_> = peek::elements(b, at).collect();
                let was: Vec<_> = old::elements(b, at).collect();
                prop_assert_eq!(&new, &was, "elements at {}: {}", at, s);
                for key in ["model", "type", "id", "stream_options"] {
                    let new = peek::last_member(b, at, key).map(|m| m.map(|m| (m.key, m.value)));
                    let was = old::last_member(b, at, key).map(|m| m.map(|m| (m.key, m.value)));
                    prop_assert_eq!(new, was, "last {} at {}: {}", key, at, s);
                }
                if let Some(end) = old::value_end(b, at) {
                    prop_assert_eq!(
                        peek::str_value(b, (at, end)),
                        old::str_value(b, (at, end)),
                        "str_value at {}: {}",
                        at,
                        s
                    );
                    for want in ["model", "image", "", "é😀"] {
                        prop_assert_eq!(
                            peek::str_is(b, (at, end), want),
                            old::str_is(b, (at, end), want),
                            "str_is {} at {}: {}",
                            want,
                            at,
                            s
                        );
                    }
                    prop_assert_eq!(
                        peek::has_typed_member(b, (at, end), TYPES),
                        old::has_typed_member(b, (at, end), TYPES),
                        "has_typed_member at {}: {}",
                        at,
                        s
                    );
                }
            }
            prop_assert_eq!(peek::root_open(b), old::root_open(b), "{}", s);
            prop_assert_eq!(
                peek::has_typed_member(b, (0, b.len()), TYPES),
                old::has_typed_member(b, (0, b.len()), TYPES),
                "{}",
                s
            );
            let (n, o) = (peek::structure(b), old::structure(b));
            prop_assert_eq!((n.objects, n.tokens), (o.objects, o.tokens), "{}", s);
            let edits: [(Edit, Edit); 5] = [
                (peek::remove_root_nulls, old::remove_root_nulls),
                (
                    |b| peek::remove_root_members(b, "stream_options"),
                    |b| old::remove_root_members(b, "stream_options"),
                ),
                (
                    |b| peek::set_root_member(b, "store", b"false"),
                    |b| old::set_root_member(b, "store", b"false"),
                ),
                (
                    |b| match peek::root_members(b).and_then(|m| m.first().copied()) {
                        Some(m) => peek::remove_element_members(b, m.value.0, "type"),
                        None => false,
                    },
                    |b| match old::root_members(b).and_then(|m| m.first().copied()) {
                        Some(m) => old::remove_element_members(b, m.value.0, "type"),
                        None => false,
                    },
                ),
                (
                    |b| match peek::root_members(b) {
                        Some(m) => {
                            let spans: Vec<_> = m.iter().map(peek::Member::span).collect();
                            peek::remove_items(b, &spans, |k| k % 2 == 0)
                        }
                        None => false,
                    },
                    |b| match old::root_members(b) {
                        Some(m) => {
                            let spans: Vec<_> = m.iter().map(old::Member::span).collect();
                            old::remove_items(b, &spans, |k| k % 2 == 0)
                        }
                        None => false,
                    },
                ),
            ];
            for (i, (new, was)) in edits.iter().enumerate() {
                let (mut x, mut y) = (b.to_vec(), b.to_vec());
                prop_assert_eq!(new(&mut x), was(&mut y), "edit {} changed: {}", i, s);
                prop_assert_eq!(x, y, "edit {}: {}", i, s);
            }
            Ok(())
        },
    );
}

/// The decoded root keys, in order, duplicates kept: what serde's map visitor sees.
fn serde_root_keys(b: &[u8]) -> Option<Vec<(String, Value)>> {
    struct Entries(Vec<(String, Value)>);
    impl<'de> serde::Deserialize<'de> for Entries {
        fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
            struct V;
            impl<'de> serde::de::Visitor<'de> for V {
                type Value = Entries;
                fn expecting(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
                    f.write_str("an object")
                }
                fn visit_map<A: serde::de::MapAccess<'de>>(
                    self,
                    mut m: A,
                ) -> Result<Entries, A::Error> {
                    let mut out = Vec::new();
                    while let Some(e) = m.next_entry::<String, Value>()? {
                        out.push(e);
                    }
                    Ok(Entries(out))
                }
            }
            d.deserialize_map(V)
        }
    }
    serde_json::from_slice::<Entries>(b).ok().map(|e| e.0)
}

/// What a `Value` of the tree costs in [`peek::Structure`] terms: non-empty objects, and every
/// `{`, `[`, `,` and `:` the writer put outside a string.
fn structure_of(v: &J) -> (usize, usize) {
    match v {
        J::Arr(a) => a
            .iter()
            .map(structure_of)
            .fold((0, 1 + a.len().saturating_sub(1)), |(o, t), (o2, t2)| {
                (o + o2, t + t2)
            }),
        J::Obj(m) => m.iter().map(|(_, x)| structure_of(x)).fold(
            (
                usize::from(!m.is_empty()),
                1 + m.len().saturating_sub(1) + m.len(),
            ),
            |(o, t), (o2, t2)| (o + o2, t + t2),
        ),
        _ => (0, 0),
    }
}

/// On valid JSON the span reads find what serde finds: the root members' keys (decoded) and
/// values, in order with duplicates; where the root value ends; and the structure count.
#[test]
fn prop_span_reads_match_serde() {
    check("prop_span_reads_match_serde", input(), |input| {
        if !input.valid {
            return Ok(());
        }
        let b = &input.bytes[..];
        let s = shown(b);
        let first = b.iter().position(|c| !c.is_ascii_whitespace()).unwrap();
        let end = peek::value_end(b, first).expect("a valid value ends");
        prop_assert!(
            b[end..].iter().all(u8::is_ascii_whitespace),
            "value ends at {} of {}: {}",
            end,
            b.len(),
            s
        );
        if let Some(tree) = &input.tree {
            let n = peek::structure(b);
            prop_assert_eq!((n.objects, n.tokens), structure_of(tree), "{}", s);
        }
        let Some(entries) = serde_root_keys(b) else {
            prop_assert_eq!(peek::root_members(b).map(|m| m.len()), None, "{}", s);
            return Ok(());
        };
        let members = peek::root_members(b).expect("a valid object has members");
        prop_assert_eq!(members.len(), entries.len(), "{}", s);
        for (m, (key, value)) in members.iter().zip(&entries) {
            let decoded = peek::str_value(b, (m.key.0 - 1, m.key.1 + 1));
            prop_assert_eq!(decoded.as_deref(), Some(key.as_str()), "{}", s);
            prop_assert!(m.key_is(b, key), "{}", s);
            let v: Value = serde_json::from_slice(&b[m.value.0..m.value.1]).unwrap();
            prop_assert_eq!(&v, value, "{}", s);
        }
        Ok(())
    });
}
